import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2021-05-13","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-05-13","date":"2021-05-13T00:00:00.000Z","updated":"2021-05-15T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","BlueStore"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-05-13.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-05-13.md","lastUpdated":1780460162000}'),o={name:"posts/2021/Ceph_Performance_Meeting_2021-05-13.md"};function r(n,e,s,h,u,c){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="与会人员" tabindex="-1">与会人员 <a class="header-anchor" href="#与会人员" aria-label="Permalink to &quot;与会人员&quot;">​</a></h4><ul><li>Josh</li><li>Corey（预计稍后加入）</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新项目讨论</strong></p><ul><li>Josh提出了一个即将开始的面试项目，旨在通过收集大量数据来了解最有用的信息，并讨论了如何简化数据收集和模式变更以避免系统脆弱性。</li></ul></li><li><p><strong>数据存储和查询</strong></p><ul><li>讨论了使用JSON格式存储数据，并利用数据库（如PostgreSQL）的JSON支持进行查询。提出在大量性能数据下，可能需要对JSON数据进行索引以提高查询速度。</li></ul></li><li><p><strong>Ceph性能优化</strong></p><ul><li>讨论了Ceph BlueStore的缓存策略，特别是关于小写操作的直接I/O和缓存使用。Adam提出一个PR，旨在改变小写操作的缓存策略，以避免双重缓存问题。</li></ul></li><li><p><strong>性能测试和分析</strong></p><ul><li>分享了关于omapbench测试的更新，特别是在不同Ceph版本间的性能差异。讨论了RocksDB的缓存命中率和性能问题，特别是在删除操作后的性能下降。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要进一步测试和分析BlueStore的缓存策略，特别是直接I/O和小写操作的缓存使用。</li><li>计划引入额外的配置参数来控制页面缓存的使用，以便更好地进行基准测试和性能优化。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Adam将继续完善PR，以提供更灵活的缓存控制选项。</li><li>进行更多的性能测试，特别是关注RocksDB的缓存命中率和删除操作后的性能恢复。</li><li>探讨和实验RocksDB的compaction策略，以优化性能。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li>讨论了旧版本Ceph集群中使用文件存储（FileStore）遇到的问题，特别是inode扫描和目录列表性能问题。</li><li>分享了在实际部署中遇到的性能问题和解决方案，特别是在使用缓存和直接I/O时的权衡。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，感谢所有参与者的贡献，并期待下周的会议。</li></ul>',13)])])}const _=a(o,[["render",r]]);export{p as __pageData,_ as default};
